export function LanguageSwitcher({
  language = "{{language}}",
  showFlag = {{showFlag}},
  accent = "{{accent}}",
  userName = "{{userName}}",
}) {
  const greetings = {
    en: `Welcome back, ${userName}`,
    es: `Bienvenido de nuevo, ${userName}`,
    ar: `\u0623\u0647\u0644\u0627\u064B \u0628\u0643 \u0645\u062C\u062F\u062F\u0627\u064B\u060C ${userName}`,
  };
  return (
    <div lang={language} dir="auto" style={{ font: "15px/1.6 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", padding: 20, borderRadius: 12, width: 300, boxSizing: "border-box" }}>
      {showFlag && <span style={{ display: "inline-block", fontWeight: 700, fontSize: 10, textTransform: "uppercase", padding: "3px 9px", borderRadius: 999, marginBottom: 12, background: accent }}>{language}</span>}
      <p style={{ margin: 0, fontWeight: 600 }}>{greetings[language]}</p>
    </div>
  );
}
